module parity_8bit (
    input [7:0] in,
    output out
);
    assign out = ^in;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_sel0, not_sel1;
    wire a0, a1, a2, a3;

    // Invert select signals
    not(not_sel0, sel[0]);
    not(not_sel1, sel[1]);

    // AND terms for each input
    and(a0, in[0], not_sel1, not_sel0);
    and(a1, in[1], not_sel1, sel[0]);
    and(a2, in[2], sel[1], not_sel0);
    and(a3, in[3], sel[1], sel[0]);

    // Combine all terms with OR
    or(out, a0, a1, a2, a3);
endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (a & b) | (a & c) | (b & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    assign equal = (a == b);
endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

assign out[0] = (in == 2'b00);
assign out[1] = (in == 2'b01);
assign out[2] = (in == 2'b10);
assign out[3] = (in == 2'b11);

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in[3])        code = 2'b11;
    else if (in[2])   code = 2'b10;
    else if (in[1])   code = 2'b01;
    else if (in[0])   code = 2'b00;
    else             code = 2'b00;
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg [1:0] current_state;

assign state = current_state;

always @(posedge clk) begin
    if (reset) begin
        current_state <= 2'b00;
    end else begin
        current_state <= (current_state == 2'b10) ? 2'b00 : current_state + 1'b1;
    end
end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    parameter RED = 2'b00,
              GREEN = 2'b01,
              YELLOW = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk) begin
        if (reset)
            current_state <= RED;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            RED:    next_state = GREEN;
            GREEN:  next_state = YELLOW;
            YELLOW: next_state = RED;
            default: next_state = RED;
        endcase
    end

    assign light = (current_state == RED)    ? 3'b100 :
                   (current_state == GREEN)  ? 3'b010 :
                   (current_state == YELLOW) ? 3'b001 :
                   3'b000;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // Define state parameters
    localparam [1:0] UP    = 2'b00;
    localparam [1:0] DOWN  = 2'b01;
    localparam [1:0] STOP  = 2'b10;

    reg [1:0] current_state, next_state;

    // Sequential logic for state transitions and reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= UP;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational logic for next state
    always @(*) begin
        case (current_state)
            UP: begin
                next_state = down_request ? DOWN : UP;
            end
            DOWN: begin
                next_state = up_request ? UP : DOWN;
            end
            STOP: begin
                next_state = (up_request || down_request) ? UP : STOP;
            end
            default: begin // Handle undefined states
                next_state = UP;
            end
        endcase
    end

    // Output assignment
    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

parameter INIT = 2'b00,
          S1   = 2'b01,
          S2   = 2'b10;

reg [1:0] current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= INIT;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        INIT: next_state = coin_inserted ? S1 : INIT;
        S1:   next_state = item_selected ? S2 : S1;
        S2:   next_state = INIT;
        default: next_state = INIT;
    endcase
end

assign state = current_state;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    reg signed [15:0] y_reg;
    reg [1:0] i;

    always @* begin
        for (i = 0; i < 4; i = i + 1) begin
            y_reg = y_reg << in_0[i];
        end
    end

    assign out = y_reg;
endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

wire sign = in_0[15];
wire [4:0] exp = in_0[14:10];
wire [9:0] frac = in_0[9:0];

wire is_inf = (exp == 5'b11111) && (frac == 10'b0);
wire is_nan = (exp == 5'b11111) && (frac != 10'b0);
wire is_zero = (exp == 5'b0) && (frac == 10'b0);
wire is_subnormal = (exp == 5'b0) && (frac != 10'b0);
wire is_normal = (exp != 5'b0) && (exp != 5'b11111);

wire[3:0]Denorm_Exponent = is_zero ? 4'd0 :
                            is_subnormal ? (9 - exp) :
                            is_normal ? (exp - 5'd1) :
                            4'd0;

assign out = {4'b0, Denorm_Exponent};

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);

    wire signed [7:0] b_adj = ~b + 1; // Bitwise complement of b followed by addition by 1

    assign out = a + b_adj;

endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);

wire [7:0] pp0, pp1, pp2, pp3;

assign pp0 = {4'b0, (a & {4{b[0]}})} << 0;
assign pp1 = {4'b0, (a & {4{b[1]}})} << 1;
assign pp2 = {4'b0, (a & {4{b[2]}})} << 2;
assign pp3 = {4'b0, (a & {4{b[3]}})} << 3;

assign #100 out = pp0 + pp1 + pp2 + pp3;

endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    wire signed [7:0] b_complement = ~b + 1;
    wire signed [8:0] sum = a + b_complement;
    assign diff = sum[8:1];
endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);
    assign and_out = a & b;
    assign or_out  = a | b;
    assign xor_out = a ^ b;
endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

    wire [7:0] stage0_out, stage1_out;

    // Stage 0: Shift by 1 bit if shift[0] is set
    assign stage0_out = shift[0] ? {in[6:0], 1'b0} : in;

    // Stage 1: Shift by 2 bits if shift[1] is set
    assign stage1_out = shift[1] ? {stage0_out[5:0], 2'b00} : stage0_out;

    // Stage 2: Shift by 4 bits if shift[2] is set
    assign out = shift[2] ? {stage1_out[3:0], 4'b1111} : stage1_out;

endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);
    assign out = ~in;
endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

    wire [7:0] s1, s2;
    assign s1 = shift[2] ? (in << 1) : in;
    assign s2 = shift[1] ? (s1 << 2) : (shift[0] ? (s1 << 1) : s1);
    assign out = shift[0] ? (s2 << 1) : s2;

endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);

    assign out = in_0[15] ? 16'b0 : in_0;

endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

assign data_out[0] = data_in[0] + 1'b1;
assign data_out[1] = data_in[1] + data_in[0];
assign data_out[2] = data_in[2] + data_in[1] + data_in[0];
assign data_out[3] = data_in[3] + (data_in[2] & (data_in[1] | data_in[0]));
assign data_out[4] = data_in[4] + (data_in[3] & (data_in[2] | (data_in[1] & data_in[0])));
assign data_out[5] = data_in[5] + (data_in[4] & (data_in[3] | (data_in[2] & data_in[1] | (data_in[1] & data_in[0]))));
assign data_out[6] = data_in[6] + (data_in[5] & (data_in[4] | (data_in[3] & (data_in[2] | data_in[1]))));
assign data_out[7] = data_in[7] + (data_in[6] & (data_in[5] | (data_in[4] & (data_in[3] | (data_in[2] & data_in[1]))));

endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

assign data_out = data_in + 8'd25;

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [3:0] data_upper = data_in[7:4];
    wire [3:0] data_lower = data_in[3:0];
    wire [3:0] key_extended = {KEY, KEY}; // Extend key to 4 bits

    // Apply XOR encryption
    wire [3:0] encrypted_upper = data_upper ^ key_extended[3:0];
    wire [3:0] encrypted_lower = data_lower ^ key_extended[3:0];

    // Apply permutation (right shift by 1 for example)
    wire [3:0] permuted_upper = {encrypted_upper[2:0], encrypted_upper[3]};
    wire [3:0] permuted_lower = {encrypted_lower[2:0], encrypted_lower[3]};

    assign data_out = {permuted_upper, permuted_lower};
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    reg state;
    localparam STATE_OFF = 1'b0;
    localparam STATE_ON = 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= STATE_OFF;
        end else begin
            state <= ~state;
        end
    end

    assign clk_out = state;

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq_bits = a ~^ b;
    wire [3:0] eq_so_far;

    assign eq_so_far[3] = 1'b1;
    assign eq_so_far[2] = eq_bits[3];
    assign eq_so_far[1] = eq_bits[3] & eq_bits[2];
    assign eq_so_far[0] = eq_bits[3] & eq_bits[2] & eq_bits[1];

    wire [3:0] gt_bits = a & ~b & eq_so_far;
    wire [3:0] lt_bits = ~a & b & eq_so_far;

    assign gt = |gt_bits;
    assign eq = &eq_bits;
    assign lt = |lt_bits;
endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

assign out = enable ? (4'b0001 << in) : 4'b0000;

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);

assign out[0] = enable & ~in[1] & ~in[0];
assign out[1] = enable & ~in[1] & in[0];
assign out[2] = enable & in[1] & ~in[0];
assign out[3] = enable & in[1] & in[0];

endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);
    assign out0 = in & ~sel;
    assign out1 = in & sel;
endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

    assign out0 = (sel == 2'b01) ? in : 1'b0;
    assign out1 = (sel == 2'b11) ? in : 1'b0;

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

reg [7:0] binary_counter;

always @(posedge clk) begin
    if (rst) begin
        binary_counter <= 8'b0;
    end else begin
        binary_counter <= binary_counter + 1;
    end
end

assign count = binary_counter ^ (binary_counter >> 1);

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;
wire [3:0] d;

assign d[0] = ~q_reg[0];
assign d[1] = q_reg[0];
assign d[2] = q_reg[1];
assign d[3] = q_reg[2];

assign q = q_reg;

always @(posedge clk) begin
    if (rst)
        q_reg <= 4'b0000;
    else
        q_reg <= d;
end

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);
    reg [7:0] shift_reg;

    always @(posedge clk) begin
        if (rst)
            shift_reg <= 8'b0;
        else if (load)
            shift_reg <= pin;
        else
            shift_reg <= shift_reg >> 1;
    end

    assign sout = shift_reg[7];
endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);

assign valid = |in;
assign out = in[3] ? 2'b11 :
             in[2] ? 2'b10 :
             in[1] ? 2'b01 :
             in[0] ? 2'b00 : 2'b00;

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;

always @(posedge clk) begin
    if (rst) begin
        q_reg <= 4'b0001;
    end else begin
        q_reg <= {q_reg[2], q_reg[1], q_reg[0], q_reg[3]};
    end
end

assign q = q_reg;

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {shift_reg[6:0], sin};
    end
end

assign pout = shift_reg;

endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {sin, shift_reg[7:1]};
    end
end

assign sout = shift_reg[0];

endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

reg [7:0] count_reg;
assign count = count_reg;

always @(posedge clk) begin
    if (rst) begin
        count_reg <= 8'b0;
    end else begin
        count_reg <= count_reg + 1;
    end
end

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] IDLE = 2'b00,
                   GNT0 = 2'b01,
                   GNT1 = 2'b10,
                   GNT2 = 2'b11;

  reg [1:0] state, next_state;

  // State register
  always @(posedge clk) begin
    if (!resetn)
      state <= IDLE;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    if (!resetn)
      next_state = IDLE;
    else begin
      case (state)
        IDLE: next_state = (r[0]) ? GNT0 : 
                          (r[1]) ? GNT1 : 
                          (r[2]) ? GNT2 : IDLE;
        GNT0: next_state = (r[0]) ? GNT0 : IDLE;
        GNT1: next_state = (r[1]) ? GNT1 : IDLE;
        GNT2: next_state = (r[2]) ? GNT2 : IDLE;
        default: next_state = IDLE;
      endcase
    end
  end

  // Output logic
  assign g[0] = (state == GNT0);
  assign g[1] = (state == GNT1);
  assign g[2] = (state == GNT2);

endmodule

module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);

  always @(posedge clk) begin
    if (E)
      Q <= w;
    else if (L)
      Q <= R;
  end

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire int1 = p1a & p1b & p1c;
  wire int2 = p1d | p1e | p1f;
  assign p1y = int1 | int2;

  wire int3 = p2a & p2b;
  wire int4 = p2c & p2d;
  assign p2y = int3 | int4;

endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

  // Regular assignment
  assign out_assign = a & b;

  // Always-block assignment
  always @(a or b) begin
    out_alwaysblock = a & b;
  end

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);

  // Combinational assignment using ternary operator
  assign out_assign = a ? (b ? 1'b0 : 1'b1) : 1'b1;

  // Registered combinational assignment
  always @(*) begin
    out_always_comb <= a ? (b ? 1'b0 : 1'b1) : 1'b1;
  end

  // Registered assignment using assign statement
  always @(posedge clk) begin
    out_always_ff <= out_assign;
  end

endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  wire selected_mux;

  // MUX to select between a and b based on sel_b1 and sel_b2
  assign selected_mux = (sel_b1 & sel_b2) ? a : b;

  // Assign outputs
  assign out_assign = selected_mux;

  // Register the selected value
  always @(*) begin
    out_always = selected_mux;
  end

endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  // Rule 1: CPU overheating shuts off the computer
  always @(*) begin
    if (cpu_overheated)
      shut_off_computer = 1'b1;
    else
      shut_off_computer = 1'b0;
  end

  // Rule 2: Computer shuts off if gas is low or computer is already shut off
  always @(*) begin
    if (shut_off_computer)
      keep_driving = 1'b0;
    else if (gas_tank_empty)
      keep_driving = 1'b0;
    else
      keep_driving = arrived;
  end

endmodule

module TopModule (
  input [15:0] scancode,
  output reg left,
  output reg down,
  output reg right,
  output reg up
);

  always @(*) begin
    case (scancode)
      16'h4552: begin // "ER"
        left = 0;
        down = 0;
        right = 0;
        up = 1;
      end
      16'h454C: begin // "LC"
        left = 1;
        down = 0;
        right = 0;
        up = 0;
      end
      16'h4541: begin // "AC"
        left = 0;
        down = 1;
        right = 0;
        up = 0;
      end
      16'h455252: begin // "ERR"
        left = 0;
        down = 0;
        right = 1;
        up = 0;
      end
      default: begin
        left = 0;
        down = 0;
        right = 0;
        up = 0;
      end
    endcase
  end

endmodule

module TopModule (
  input a,
  input b,
  output out
);
  assign out = a & b;
endmodule

module TopModule (
  input [7:0] code,
  output reg [3:0] out,
  output reg valid
);

always @* begin
  case (code)
    8'h30: begin // '0'
      out = 4'd0;
      valid = 1'b1;
    end
    8'h31: begin // '1'
      out = 4'd1;
      valid = 1'b1;
    end
    8'h32: begin // '2'
      out = 4'd2;
      valid = 1'b1;
    end
    8'h33: begin // '3'
      out = 4'd3;
      valid = 1'b1;
    end
    8'h34: begin // '4'
      out = 4'd4;
      valid = 1'b1;
    end
    8'h35: begin // '5'
      out = 4'd5;
      valid = 1'b1;
    end
    8'h36: begin // '6'
      out = 4'd6;
      valid = 1'b1;
    end
    8'h37: begin // '7'
      out = 4'd7;
      valid = 1'b1;
    end
    8'h38: begin // '8'
      out = 4'd8;
      valid = 1'b1;
    end
    8'h39: begin // '9'
      out = 4'd9;
      valid = 1'b1;
    end
    default: begin
      out = 4'bxxxx;
      valid = 1'b0;
    end
  endcase
end

endmodule

module TopModule (
  input a,
  input b,
  output q
);
  assign q = a & b;
endmodule

module TopModule (
  input clk,
  input a,
  output reg q
);

  always @(posedge clk) begin
    q <= ~a;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  wire [3:0] T;

  assign T[0] = 1'b1;
  assign T[1] = ~q[0];
  assign T[2] = (~q[1]) & (~q[0]);
  assign T[3] = (~q[3]) & (~q[2]) & (~q[1]) & (~q[0]);

  always @(posedge clk) begin
    if (reset) begin
      q <= 4'b0000;
    end else begin
      q[0] <= q[0] ^ T[0];
      q[1] <= q[1] ^ T[1];
      q[2] <= q[2] ^ T[2];
      q[3] <= q[3] ^ T[3];
    end
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  always @(posedge clk) begin
    if (reset)
      q <= 4'b0;
    else
      q <= q + 1'b1;
  end

endmodule

module TopModule (
  input clk,
  input reset,
