module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  localparam [1:0] IDLE = 2'b00,
                   WORKING = 2'b01,
                   STOPPED = 2'b10;

  reg [1:0] current_state, next_state;

  // State register with asynchronous reset
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    if (train_valid && train_taken)
      next_state = current_state;
    else begin
      case (current_state)
        IDLE:    next_state = WORKING;
        WORKING: next_state = STOPPED;
        STOPPED: next_state = IDLE;
        default: next_state = IDLE;
      endcase
    end
  end

  // Output assignment
  assign state = current_state;

endmodule

