module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  localparam s0 = 2'b00,
             s1 = 2'b01,
             s2 = 2'b10;

  reg [1:0] current_state, next_state;

  always @(posedge clk or negedge aresetn) begin
    if (!aresetn)
      current_state <= s0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    next_state = current_state;
    z = 0;

    case (current_state)
      s0: begin
        if (x) begin
          next_state = s1;
          z = 0;
        end else begin
          next_state = s0;
          z = 0;
        end
      end
      s1: begin
        if (x) begin
          next_state = s2;
          z = 0;
        end else begin
          next_state = s0;
          z = 1;
        end
      end
      s2: begin
        if (x) begin
          next_state = s2;
          z = 0;
        end else begin
          next_state = s0;
          z = 1;
        end
      end
      default: begin
        next_state = s0;
        z = 0;
      end
    endcase
  end

endmodule

module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] p;
  wire [7:0] g;
  wire [8:0] c;

  assign c[0] = 1'b0;

  // Generate propagate and generate signals with delays
  assign #1 p[0] = a[0] ^ b[0];
  assign #1 g[0] = a[0] & b[0];

  // Generate with delay for each bit
  genvar i;
  generate
    for (i = 1; i < 8; i = i + 1) begin : pg_gen
      assign #1 p[i] = a[i] ^ b[i];
      assign #1 g[i] = a[i] & b[i];
    end
  endgenerate

  // Carry computation with delays
  assign #2 c[1] = g[0] | (p[0] & c[0]);
  assign #2 c[2] = g[1] | (p[1] & c[1]);
  assign #2 c[3] = g[2] | (p[2] & c[2]);
  assign #2 c[4] = g[3] | (p[3] & c[3]);
  assign #2 c[5] = g[4] | (p[4] & c[4]);
  assign #2 c[6] = g[5] | (p[5] & c[5]);
  assign #2 c[7] = g[6] | (p[6] & c[6]);
  assign #2 c[8] = g[7] | (p[7] & c[7]);

  // Sum computation with delays
  assign #1 s[0] = p[0] ^ c[0];
  assign #2 s[1] = p[1] ^ c[1];
  assign #2 s[2] = p[2] ^ c[2];
  assign #2 s[3] = p[3] ^ c[3];
  assign #2 s[4] = p[4] ^ c[4];
  assign #2 s[5] = p[5] ^ c[5];
  assign #2 s[6] = p[6] ^ c[6];
  assign #2 s[7] = p[7] ^ c[7];

  assign overflow = c[8];

endmodule

