module TopModule (
  input clk,
  input j,
  input k,
  input areset,
  output out
);

  reg current_state;
  reg next_state;

  localparam OFF = 1'b0;
  localparam ON  = 1'b1;

  // Combinational logic for next state
  always @(*) begin
    case (current_state)
      OFF: next_state = j ? ON : OFF;
      ON:  next_state = k ? OFF : ON;
      default: next_state = OFF;
    endcase
  end

  // Sequential logic with asynchronous reset
  always @(posedge clk, posedge areset) begin
    if (areset)
      current_state <= OFF;
    else
      current_state <= next_state;
  end

  // Output assignment
  assign out = current_state;

endmodule

module TopModule (
  input clk,
  input j,
  input k,
  input reset,
  output out
);

  reg state;
  reg next_state;

  localparam IDLE = 1'b0;
  localparam BUSY = 1'b1;

  // Combinational logic for next state
  always @(*) begin
    case (state)
      IDLE: next_state = j ? BUSY : IDLE;
      BUSY: next_state = k ? IDLE : BUSY;
      default: next_state = IDLE;
    endcase
  end

  // Sequential logic for state transition
  always @(posedge clk) begin
    if (reset)
      state <= IDLE;
    else
      state <= next_state;
  end

  // Output logic
  assign out = (state == BUSY);

endmodule

module TopModule (
