module TopModule (
  input clk,
  input d,
  input r,
  output logic q
);

  localparam [WIDTH-1:0] RESET = 0;
  localparam [WIDTH-1:0] IDLE = 1;
  localparam [WIDTH-1:0] ACQUIRED = 2;
  localparam [WIDTH-1:0] EXTENSION = 3;

  localparam WIDTH = 4; // Adjust based on state encoding needs

  reg [WIDTH-1:0] current_state, next_state;

  // State register with synchronous reset
  always @(posedge clk) begin
    if (r)
      current_state <= RESET;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      RESET:   next_state = IDLE;
      IDLE:    next_state = d ? ACQUIRED : IDLE;
      ACQUIRED: next_state = d ? EXTENSION : ACQUIRED;
      EXTENSION: next_state = d ? EXTENSION : IDLE;
      default: next_state = RESET;
    endcase
  end

  // Output logic
  always @(*) begin
    q = (current_state == ACQUIRED);
  end

endmodule

