  assign c3 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
  assign c4 = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

  assign sum[0] = P[0];
  assign sum[1] = P[1] ^ c1;
  assign sum[2] = P[2] ^ c2;
  assign sum[3] = P[3] ^ c3;
  assign sum[4] = c4;

