  assign next_state[0] = ~q[0];  // T0 is always 1

  assign next_state[1] = (a | q[0]) & ~q[1];  // T1 = (a | q[0]) & ~q[1]

  assign next_state[2] = (a | (q[0] & q[1])) & ~q[2];  // T2 = (a | (q[0] & q[1])) & ~q[2]

  always @(posedge clk) begin
    q <= next_state;
  end

endmodule

