      state_reg <= 2'b00;
    end else begin
      case (state_reg)
        2'b00: state_reg <= x ? 2'b00 : 2'b01;
        2'b01: state_reg <= x ? 2'b10 : 2'b01;
        2'b10: state_reg <= x ? 2'b00 : 2'b01;
        default: state_reg <= 2'b00;
      endcase
    end
  end

  assign z = (state_reg == 2'b00 && x) || (state_reg == 2'b01 && !x);

