    disc1 = 4'd1,
    disc2 = 4'd2,
    disc3 = 4'd3,
    disc4 = 4'd4,
    disc5 = 4'd5,
    disc6 = 4'd6,
    disc7 = 4'd7,
    disc8 = 4'd8,
    flag0 = 4'd9,
    flag1 = 4'd10,
    flag2 = 4'd11,
    flag3 = 4'd12,
    flag4 = 4'd13,
    err0  = 4'd14,
    err1  = 4'd15;

  reg [3:0] current_state, next_state;

  always @(posedge clk) begin
    if (reset)
      current_state <= disc0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      disc0: next_state = in ? disc1 : disc0;
      disc1: next_state = in ? disc2 : disc0;
      disc2: next_state = in ? disc3 : disc0;
      disc3: next_state = in ? disc4 : disc0;
      disc4: next_state = in ? disc5 : disc0;
      disc5: next_state = in ? disc6 : disc0;
      disc6: next_state = in ? disc7 : disc0;
      disc7: next_state = in ? disc8 : disc0;
      disc8: next_state = in ? flag0 : disc0;
      flag0: next_state = in ? flag1 : flag0;
      flag1: next_state = in ? flag2 : flag1;
      flag2: next_state = in ? flag3 : flag2;
      flag3: next_state = in ? flag4 : flag3;
      flag4: next_state = in ? err0 : flag4;
      err0:  next_state = in ? err1 : err0;
      err1:  next_state = err1;
      default: next_state = disc0;
    endcase
  end

  assign disc = (current_state == disc8);
  assign flag = (current_state == flag4);
  assign err = (current_state == err1);

endmodule

module TopModule (
