module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);

  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10;

  reg [1:0] current_state, next_state;
  reg done_reg;

  // State register
  always @(posedge clk) begin
    if (reset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Done register
  always @(posedge clk) begin
    if (reset)
      done_reg <= 1'b0;
    else
      done_reg <= (current_state == S2) ? 1'b0 : in[3] ? 1'b1 : done_reg;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S0: next_state = in[3] ? S1 : S0;
      S1: next_state = in[3] ? S2 : S0;
      S2: next_state = in[3] ? S2 : S0;
      default: next_state = S0;
    endcase
  end

  // Output logic
  assign done = done_reg;

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  reg [1:0] current_state, next_state;
  reg [2:0] counter;
  reg done_reg;

  // State definitions
  localparam [1:0] IDLE = 2'b00,
                   CHECK = 2'b01,
                   CORRECT = 2'b10,
                   WRONG = 2'b11;

  // State transition logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = in ? CHECK : IDLE;
      CHECK: next_state = in ? WRONG : CORRECT;
      CORRECT: next_state = IDLE;
      WRONG: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

  // State register with synchronous reset
  always @(posedge clk) begin
    if (reset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Counter logic for done signal
  always @(posedge clk) begin
    if (reset) begin
      counter <= 3'b0;
      done_reg <= 1'b0;
    end else begin
      if (current_state == CORRECT) begin
        if (counter == 3'd4) begin
          counter <= 3'b0;
          done_reg <= 1'b1;
        end else begin
          counter <= counter + 1;
          done_reg <= 1'b0;
        end
      end else begin
        counter <= 3'b0;
        done_reg <= 1'b0;
      end
    end
  end

  assign done = done_reg;

endmodule

