  wire t1, t2, t3, t4, t5, t6, t7, t8, t9, t10;

  // Inverters for each input as needed
  not #10 (not_a, a);
  not #10 (not_b, b);
  not #10 (not_c, c);
  not #10 (not_d, d);

  // Intermediate terms using AND, OR, NOT
  and #10 (t1, not_a, not_b);
  or  #10 (t2, t1, not_c);
  and #10 (t3, t2, d);
  or  #10 (t4, t3, not_d);
  and #10 (t5, t4, b);
  or  #10 (t6, t5, c);
  and #10 (t7, t6, not_a);
  or  #10 (t8, t7, d);
  and #10 (t9, t8, not_b);
  or  #10 (t10, t9, not_c);
  and #10 (out, t10, d);

