module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  localparam LEFT = 1'b0;
  localparam RIGHT = 1'b1;

  reg state;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= LEFT;
    end else begin
      case (state)
        LEFT: state <= (bump_left) ? RIGHT : LEFT;
        RIGHT: state <= (bump_right) ? LEFT : RIGHT;
        default: state <= LEFT;
      endcase
    end
  end

  assign walk_left = (state == LEFT);
  assign walk_right = (state == RIGHT);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam [1:0] AA = 2'b00,
                   BL = 2'b01,
                   BR = 2'b10,
                   RR = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= AA;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      AA: begin
        if (bump_left)
          next_state = BL;
        else if (bump_right)
          next_state = BR;
        else if (ground)
          next_state = RR;
        else
          next_state = AA;
      end
      BL: begin
        if (bump_left)
          next_state = BR;
        else if (bump_right)
          next_state = BL;
        else if (ground)
          next_state = RR;
        else
          next_state = AA;
      end
      BR: begin
        if (bump_left)
          next_state = RR;
        else if (bump_right)
          next_state = BL;
        else if (ground)
          next_state = RR;
        else
          next_state = AA;
      end
      RR: begin
        if (bump_left)
          next_state = BL;
        else if (bump_right)
          next_state = BR;
        else if (ground)
          next_state = RR;
        else
          next_state = AA;
      end
      default: next_state = AA;
    endcase
  end

  assign walk_left = (current_state == BL);
  assign walk_right = (current_state == BR);
  assign aaah = (current_state == AA) || (current_state == RR);

endmodule

