  wire term_a, term_b, term_c;

  not (not_x1, x[1]);
  not (not_x3, x[3]);

  and (term_a, x[0], not_x1, not_x3);
  and (term_b, x[2], not_x1, not_x3);
  and (term_c, x[1], x[2], x[3]);

  or (f, term_a, term_b, term_c);
endmodule

module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  // Define states
  localparam [2:0] INIT = 3'b000,
                   N1    = 3'b001,
                   N2    = 3'b010,
                   N3    = 3'b011,
                   N4    = 3'b100,
                   N5    = 3'b101,
                   N6    = 3'b110;

  reg [2:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (!resetn)
      current_state <= INIT;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      INIT: next_state = y ? N1 : INIT;
      N1:   next_state = x ? N2 : N1;
      N2:   next_state = x ? N3 : N2;
      N3:   next_state = x ? N4 : N3;
      N4:   next_state = x ? N5 : N4;
      N5:   next_state = x ? N6 : N5;
      N6:   next_state = INIT;
      default: next_state = INIT;
    endcase
  end

  // Output logic
  assign f = (current_state == N1);
  assign g = (current_state == N6);

endmodule

