module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [15:1] G = A[32:18];
     wire [15:1] F = A[17:2];
     wire [15:0] P = B[32:18];
     wire [15:0] Q = B[17:2];
     wire Cin = A[1];
     wire Cout = A[32];

     wire [16:1] C;
     assign C[1] = Cin;

     generate
         genvar i;
         for (i=1; i<16; i=i+1) begin : adder_loop
             wire a_xor_b, a_and_b, a_xor_b_and_not_cin;
             xor x1(a_xor_b, F[i], Q[i]);
             xor x2(P[i], G[i], C[i-1]);
             and a1(a_and_b, F[i], Q[i]);
             and a2(a_xor_b_and_not_cin, a_xor_b, C[i-1]);
             or o1(C[i], a_and_b, a_xor_b_and_not_cin);
         end
     endgenerate

     assign C32 = C[16];
     assign S[32] = Cout;
     assign S[31:16] = C[16:1];
     assign S[15:1] = P;
     assign S[0] = 0;

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);
    wire [7:0] G, P;
    wire [8:0] C;

    assign C[0] = cin;

    // Generate and propagate signals
    assign G = a & b;
    assign P = a ^ b;

    // Carry computation using look-ahead logic
    assign C[1] = G[0] | (P[0] & C[0]);
    assign C[2] = G[1] | (P[1] & C[1]);
    assign C[3] = G[2] | (P[2] & C[2]);
    assign C[4] = G[3] | (P[3] & C[3]);
    assign C[5] = G[4] | (P[4] & C[4]);
    assign C[6] = G[5] | (P[5] & C[5]);
    assign C[7] = G[6] | (P[6] & C[6]);
    assign C[8] = G[7] | (P[7] & C[7]);

    // Sum computation
    assign sum = P ^ C[7:0];

    // Carry-out
    assign cout = C[8];
endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    wire [3:0] sum_temp;
    wire [4:0] carry;

    assign carry[0] = Cin;

    // Generate full adder stages using basic gates
    assign sum_temp[0] = (A[0] ^ B[0]) ^ carry[0];
    assign carry[1] = (A[0] & B[0]) | ((A[0] ^ B[0]) & carry[0]);

    assign sum_temp[1] = (A[1] ^ B[1]) ^ carry[1];
    assign carry[2] = (A[1] & B[1]) | ((A[1] ^ B[1]) & carry[1]);

    assign sum_temp[2] = (A[2] ^ B[2]) ^ carry[2];
    assign carry[3] = (A[2] & B[2]) | ((A[2] ^ B[2]) & carry[2]);

    assign sum_temp[3] = (A[3] ^ B[3]) ^ carry[3];
    assign carry[4] = (A[3] & B[3]) | ((A[3] ^ B[3]) & carry[3]);

    // Adjust sum and carry based on 10
    wire adjust_sum = (sum_temp >= 4'd10);
    wire adjust_cout = carry[4] & (sum_temp >= 4'd10);

    assign Sum = adjust_sum ? (sum_temp - 4'd10) : sum_temp;
    assign Cout = adjust_cout ? ~carry[4] : carry[4];

endmodule

