module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    out <= 4'd0;
  end else if (valid_count) begin
    if (out + 4'd1 >= 4'd12)
      out <= 4'd0;
    else
      out <= out + 4'd1;
  end
end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg a_prev;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		a_prev <= 1'b0;
		rise <= 1'b0;
		down <= 1'b0;
	} else begin
		a_prev <= a;
		rise <= (a_prev == 1'b0) && (a == 1'b1);
		down <= (a_prev == 1'b1) && (a == 1'b0);
	}
end

endmodule

module freq_divbyeven(
    input clk,
    input rst_n,
    output clk_div,
    reg clk_div;
    parameter NUM_DIV = 6;

    reg [4:0] counter;

    // Counter logic with active-low reset
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 5'b0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 5'b0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    // Toggle output logic with active-low reset
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_div <= 1'b0;
        end else if (counter == (NUM_DIV / 2 - 1)) begin
            clk_div <= ~clk_div;
        end
    end

    // Assign output
    assign clk_div = clk_div;

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

reg [7:0] data_reg;

always @(posedge clk) begin
    if (!rst) begin
        data_reg <= 8'b0;
    end else begin
        case (fetch)
            2'b00:   data_reg <= {data[7:5], data[2:0]};
            2'b01:   data_reg <= {data[7:4], data[3:1]};
            default: data_reg <= data_reg;
        endcase
    end
end

assign ins = data_reg[2:0];
assign ad1 = data_reg[4:0];
assign ad2 = data_reg[7:1];

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire feedback;

  assign feedback = out[3] ^ out[2];

  always @(posedge clk) begin
    if (rst) begin
      out <= 4'b0;
    end else begin
      out <= {out[2:0], feedback};
    end
  end

endmodule

module right_shifter(clk, q,d);  
    input  clk;  
    input d;  
    output  [7:0] q;  

    reg [7:0] shift_reg;

    always @(posedge clk) begin
        shift_reg <= {shift_reg[6:0], d};
    end

    assign q = shift_reg;
endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	reg [3:0] reg_a, reg_b;

	// Capture data_in in clk_a domain with async reset
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn)
			reg_a <= 4'b0;
		else
			reg_a <= data_in;
	end

	// Two-stage module for clk_b domain with async reset
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			reg_b <= 4'b0;
			dataout <= 4'b0;
		end
		else begin
			reg_b <= reg_a;        // First pipeline stage
			dataout <= reg_b;      // Second pipeline stage
		end
	end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// Define states
parameter S0 = 3'd0,
          S1 = 3'd1,
          S2 = 3'd2,
          S3 = 3'd3,
          S4 = 3'd4,
          S5 = 3'd5;

reg [2:0] current_state, next_state;

// State register updates
always @(posedge CLK or posedge RST) begin
    if (RST) current_state <= S0;
    else current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S1 : S2;
        S2: next_state = IN ? S1 : S3;
        S3: next_state = IN ? S4 : S0;
        S4: next_state = IN ? S5 : S2;
        S5: next_state = IN ? S1 : S2;
        default: next_state = S0;
    endcase
end

// Output logic
always @(posedge CLK or posedge RST) begin
    if (RST) MATCH <= 1'b0;
    else MATCH <= (current_state == S5);
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shift_reg;
reg [1:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 4'b0;
        counter <= 2'b0;
    end else begin
        counter <= counter + 1;
        if (counter == 2'd3) begin
            shift_reg <= d;
        end
    end
end

assign valid_out = (counter == 2'd3);
assign dout = shift_reg[3];

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     localparam [1:0] IDLE        = 2'b00,
                     SEQ_1       = 2'b01,
                     SEQ_10      = 2'b10,
                     SEQ_101     = 2'b11;

     reg [1:0] current_state, next_state;

     // State register
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n)
            current_state <= IDLE;
         else
            current_state <= next_state;
     end

     // Next state logic
     always @(*) begin
         case (current_state)
            IDLE:        next_state = data_in ? SEQ_1 : IDLE;
            SEQ_1:       next_state = data_in ? SEQ_1 : SEQ_10;
            SEQ_10:      next_state = data_in ? SEQ_101 : IDLE;
            SEQ_101:     next_state = data_in ? SEQ_1 : SEQ_10;
            default:     next_state = IDLE;
         endcase
     end

     // Output logic
     assign sequence_detected = (current_state == SEQ_101);

endmodule
